Method.Source:
/// <summary>
/// Contains the code that does the actual job of the class.
/// </summary>
public void run()
{
    next run();

    METSalesTable metSalesTable;

    select firstonly metSalesTable 
        where metSalesTable.SalesTable == salesTable.RecId;

    if (metSalesTable.OrderProcessingStatus == METSalesOrderProcessingStatus::OptimisationCompleted
        && salesTable.METIntercompanyTransferFulfillment == NoYes::Yes)
    {
        METSalesOrderProcessHelper salesOrderProcessHelper = new METSalesOrderProcessHelper();
        salesOrderProcessHelper.autoExtractIntercompanySO(salesTable);
    }
}
